+	event: LEARNER_PROFILE_CHANGED_EVENT,
+	normalize: (raw) => typeof raw === "string" ? raw.trim().slice(0, MAX_LEARNER_PROFILE_LENGTH) : "",
+});
+
+export function loadLearnerProfile(): string {
+	return learnerProfileSetting.load();
+}
+
+export function saveLearnerProfile(profile: string): void {
+	learnerProfileSetting.save(profile);
+}
+
+export function resetLearnerProfile(): void {
+	try {
+		localStorage.removeItem(LEARNER_PROFILE_STORAGE_KEY);
+	} catch {
+		// The in-memory update below still keeps the current tab consistent.
+	}
